import { API, graphqlOperation } from "aws-amplify";
import { add_reduce_item_quantity } from "@/graphql/mutations";
export default {
  name: "StockAdjustmentDialog",
  props: {
    dialog: Boolean,
    selectedProduct: Object
  },
  data() {
    return {
      loading: false,
      showDatePicker: false,
      adjustmentType: "ADD_STOCK",
      // "add" or "reduce"
      adjustmentDate: new Date().toISOString().substr(0, 10),
      adjustmentForm: {
        totalQty: "",
        rol: "",
        atPrice: "",
        details: ""
      },
      rolOptions: [{
        title: "Low",
        value: "low"
      }, {
        title: "Medium",
        value: "medium"
      }, {
        title: "High",
        value: "high"
      }, {
        title: "Critical",
        value: "critical"
      }]
    };
  },
  computed: {
    displayDate() {
      if (!this.adjustmentDate) return "";
      const date = new Date(this.adjustmentDate);
      const day = String(date.getDate()).padStart(2, "0");
      const month = String(date.getMonth() + 1).padStart(2, "0");
      const year = date.getFullYear();
      return `${day}/${month}/${year}`;
    }
  },
  watch: {
    dialog(newVal) {
      if (newVal) {
        // Reset form when dialog opens
        this.resetForm();
      }
    }
  },
  methods: {
    is_number(evt) {
      evt = evt ? evt : window.event;
      var charCode = evt.which ? evt.which : evt.keyCode;
      if (charCode > 31 && (charCode < 48 || charCode > 57) && charCode !== 46) {
        evt.preventDefault();
      } else {
        return true;
      }
    },
    resetForm() {
      this.adjustmentForm = {
        totalQty: "",
        rol: "",
        atPrice: "",
        details: ""
      };
      this.adjustmentType = "ADD_STOCK";
      this.adjustmentDate = new Date().toISOString().substr(0, 10);
    },
    close_dialog() {
      this.$emit("update:dialog", false);
      this.$refs.form.resetValidation();
      this.resetForm();
    },
    async save_adjustment() {
      const {
        valid
      } = await this.$refs.form.validate();
      if (valid) {
        this.loading = true;
        try {
          // Prepare adjustment data
          const adjustmentData = {
            item_id: this.selectedProduct.item_id,
            stock_value: this.adjustmentForm.atPrice,
            action_type: this.adjustmentType,
            transaction_date: this.adjustmentDate,
            transaction_details: this.adjustmentForm.details,
            stock_quantity: this.adjustmentForm.totalQty || 0
          };

          // console.log("Adjustment data:", adjustmentData);

          const result = await API.graphql(graphqlOperation(add_reduce_item_quantity, {
            input: adjustmentData
          }));
          const response = JSON.parse(result.data.add_reduce_item_quantity);
          if (response.Status === "SUCCESS") {
            this.$emit("successMsg", response.Message);
            this.close_dialog();
          } else {
            this.$emit("errorMsg", response.Message || "An error occurred while saving adjustment");
          }
        } catch (error) {
          this.$emit("errorMsg", error.message || "An error occurred while saving adjustment");
        } finally {
          this.loading = false;
        }
      }
    }
  }
};
